/**
 * orc_program_new:
 * 
 * Create a new OrcProgram.  The program should be freed using
 * @orc_program_free().
 *
 * Returns: a pointer to an OrcProgram structure
 */
OrcProgram *
orc_program_new (void)
{
  OrcProgram *p;

  /* FIXME: there's no need to do this. If we guard every API
   * by having orc_init called before, we'll never end
   */
  orc_init ();

  p = orc_malloc(sizeof(OrcProgram));
  memset (p, 0, sizeof(OrcProgram));

  p->name = orc_malloc (40);
  sprintf(p->name, "func_%p", p);

  return p;
}

